const { useEffect, useRef, useState } = React;

const EVENTS = ["blur", "focusout", "focus", "focusin"];
const EVENT_COLORS = { blur: "orange", focusout: "red", focus: "blue", focusin: "green" };
const NAMES = ["A", "B"];
const STEP_MS = 160;

const nameOf = (node, inputs) => {
  const index = inputs.indexOf(node);
  return index >= 0 ? NAMES[index] : node ? "其他元素" : "null";
};

const Component = () => {
  const inputRefs = useRef([]);
  const lastFocusedRef = useRef(null);
  const [rounds, setRounds] = useState([]);

  useEffect(() => {
    const inputs = [...inputRefs.current];
    const record = event => {
      if (event.type === "focus") lastFocusedRef.current = event.target;
      const entry = { type: event.type, target: nameOf(event.target, inputs), related: nameOf(event.relatedTarget, inputs) };
      setRounds(list => {
        const current = list[0];
        const last = current?.steps[current.steps.length - 1];
        // 一次焦点切换从 blur 开始；之前没有焦点时则从 focus 开始
        const startsNew = !current || entry.type === "blur" || (entry.type === "focus" && last?.type === "focusin");
        if (startsNew) return [{ id: Date.now() + Math.random(), steps: [entry] }, ...list].slice(0, 3);
        return [{ ...current, steps: [...current.steps, entry] }, ...list.slice(1)];
      });
    };
    inputs.forEach(input => EVENTS.forEach(type => input.addEventListener(type, record)));
    return () => inputs.forEach(input => EVENTS.forEach(type => input.removeEventListener(type, record)));
  }, []);

  const switchFocus = () => {
    const [a, b] = inputRefs.current;
    const next = lastFocusedRef.current === a ? b : a;
    next.focus();
  };

  const [latest, ...history] = rounds;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-step { animation: cb-focus-step 320ms var(--tau-ease-out) both; }
          @media (prefers-reduced-motion: reduce) {
            .cb-step { animation-duration: 1ms; }
          }
        }
        @keyframes cb-focus-step {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: none; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-w-0 flex-col justify-center gap-3 rounded-tau-md border border-line-1 p-4">
          {NAMES.map((name, index) => (
            <label key={name} className="flex items-center gap-3">
              <span className="grid size-6 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-sm text-ink-2">
                {name}
              </span>
              <input
                ref={node => {
                  inputRefs.current[index] = node;
                }}
                placeholder={`点击聚焦元素 ${name}`}
                className="h-9 min-w-0 flex-1 rounded-tau-sm border border-line-1 bg-surface px-3 text-tau-body text-ink-1 outline-none focus:border-accent focus:ring-2 focus:ring-accent-soft"
              />
            </label>
          ))}
          <ui.Button
            variant="secondary"
            size="sm"
            icon={icons.ArrowDownUp}
            className="self-start"
            // 按下时不抢焦点，让切换只发生在 A 与 B 之间
            onMouseDown={event => event.preventDefault()}
            onClick={switchFocus}
          >
            用脚本切换 A / B
          </ui.Button>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">最近一次焦点变化</span>
          {latest ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {latest.steps.map((step, index) => (
                <li
                  key={`${latest.id}-${index}`}
                  className="cb-step flex items-center gap-2"
                  style={{ animationDelay: `${index * STEP_MS}ms` }}
                >
                  <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">
                    {index + 1}
                  </span>
                  <ui.Tag color={EVENT_COLORS[step.type]} className="shrink-0">
                    {step.type}
                  </ui.Tag>
                  <span className="font-tau-mono text-tau-meta text-ink-1">{step.target}</span>
                  <span className="ml-auto min-w-0 truncate font-tau-mono text-tau-tiny text-ink-3">related：{step.related}</span>
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">先聚焦 A，再点击 B</p>
          )}
          {history.length > 0 && (
            <div className="mt-auto flex flex-col gap-1 border-t border-line-2 pt-2">
              {history.map(round => (
                <span key={round.id} className="min-w-0 break-all font-tau-mono text-tau-tiny text-ink-3">
                  {round.steps.map(step => `${step.type}(${step.target})`).join(" → ")}
                </span>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const { useEffect, useRef, useState } = React;

const LISTENERS = [
  { key: "focus-bubble", type: "focus", capture: false },
  { key: "focus-capture", type: "focus", capture: true },
  { key: "focusin", type: "focusin", capture: false },
  { key: "focusout", type: "focusout", capture: false },
];
const PHASES = {
  1: { label: "捕获", color: "blue" },
  2: { label: "目标", color: "orange" },
  3: { label: "冒泡", color: "green" },
};
const FIELDS = ["用户名", "邮箱", "手机号"];

const Component = () => {
  const parentRef = useRef(null);
  const [hits, setHits] = useState({});
  const [delegated, setDelegated] = useState(null);

  useEffect(() => {
    const parent = parentRef.current;
    const handlers = LISTENERS.map(listener => {
      const handler = event => {
        // eventPhase 只在派发期间有效，先同步读出
        const phase = event.eventPhase;
        const field = event.target.dataset?.field ?? null;
        setHits(current => ({
          ...current,
          [listener.key]: { count: (current[listener.key]?.count ?? 0) + 1, phase, field, stamp: Date.now() + Math.random() },
        }));
        if (listener.type === "focusin") setDelegated(field);
        if (listener.type === "focusout") setDelegated(current => (current === field ? null : current));
      };
      parent.addEventListener(listener.type, handler, listener.capture);
      return [listener, handler];
    });
    return () => handlers.forEach(([listener, handler]) => parent.removeEventListener(listener.type, handler, listener.capture));
  }, []);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-hit { animation: cb-focus-hit 900ms var(--tau-ease-out); }
          @media (prefers-reduced-motion: reduce) {
            .cb-hit { animation: none; }
          }
        }
        @keyframes cb-focus-hit {
          from { background: var(--tau-accent-soft); }
          to { background: transparent; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(260px,42%)]">
        <div ref={parentRef} className="flex min-w-0 flex-col gap-2.5 rounded-tau-md border border-dashed border-line-1 p-3">
          <span className="font-tau-mono text-tau-meta text-ink-2">parent</span>
          {FIELDS.map(field => (
            <input
              key={field}
              data-field={field}
              placeholder={field}
              className={
                delegated === field
                  ? "h-9 min-w-0 rounded-tau-sm border border-accent bg-surface px-3 text-tau-body text-ink-1 outline-none ring-2 ring-accent-soft"
                  : "h-9 min-w-0 rounded-tau-sm border border-line-1 bg-surface px-3 text-tau-body text-ink-1 outline-none"
              }
            />
          ))}
          <span className="text-tau-sm text-ink-3">委托读数：{delegated ? `event.target 是「${delegated}」` : "无聚焦"}</span>
        </div>
        <div className="flex flex-col gap-1.5 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-center justify-between gap-2">
            <span className="text-tau-sm text-ink-3">parent 上的监听器</span>
            <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={() => setHits({})}>
              清空计数
            </ui.Button>
          </div>
          {LISTENERS.map(listener => {
            const hit = hits[listener.key];
            return (
              <div
                key={hit ? hit.stamp : listener.key}
                className={
                  hit ? "cb-hit flex items-center gap-2 rounded-tau-sm px-1.5 py-1" : "flex items-center gap-2 rounded-tau-sm px-1.5 py-1"
                }
              >
                <code className="min-w-0 truncate font-tau-mono text-tau-sm text-ink-1">
                  {listener.type}
                  {listener.capture ? ", true" : ""}
                </code>
                {hit ? (
                  <ui.Tag color={PHASES[hit.phase].color} className="shrink-0">
                    {PHASES[hit.phase].label}
                  </ui.Tag>
                ) : null}
                <span className="ml-auto shrink-0 font-tau-mono text-tau-sm text-ink-3">{hit ? `${hit.count} 次` : "未触发"}</span>
              </div>
            );
          })}
          <p className="m-0 mt-auto text-tau-sm text-ink-3">在输入框之间切换焦点，focus 冒泡监听始终收不到。</p>
        </div>
      </div>
    </div>
  );
};
